INSERT INTO "pending_actions" VALUES('rjsjAupo','reply_mail','{"to": "emmanuel.gasparini@reactive-executive.com", "subject": "RE: mission DG de transition à temps partiel", "body": "Bonjour Emmanuel,\n\nMerci pour ce contact.\n\nAprès lecture, cette mission ne correspond pas à mon positionnement actuel : j''interviens en tant que manager de transition DSI/CTO sur des entreprises de 1 000 collaborateurs et plus, avec un mandat IT exécutif à temps plein.\n\nDeux points me mettent hors scope ici :\n- La taille de la structure (40 ETP) est très en deçà de mes cibles habituelles.\n- Le périmètre DG est différent de mon domaine d''expertise, qui reste la direction des systèmes d''information et des opérations IT.\n\nJe ne souhaite donc pas postuler sur cette opportunité.\n\nSi vous avez à l''avenir des mandats DSI/CTO de transition sur des entreprises mid-market (industrie, services, santé, banque/assurance), je suis preneur.\n\nBien cordialement,\nJay"}','executed',NULL,'2026-07-23 13:29:15','2026-07-23 17:04:57',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('HiyBGTKN','calendar_event','{"subject": "Meeting BlueBirds – David Gallot / Jayson (Yneia)", "start_iso": "<UNKNOWN>", "end_iso": "<UNKNOWN>", "attendees": ["jay@inovops.com", "david.gallot@bluebirds.partners"], "body": ""}','failed','liste noire : fin de l''évènement avant ou égale au début','2026-07-23 15:29:03','2026-07-23 17:05:22',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('xc8oapvt','reply_mail','{"to": "emmanuel.gasparini@reactive-executive.com", "subject": "RE: Nouvelle mission de transition - directeur R&D édition logiciells", "body": "Bonjour Emmanuel,\n\nMerci pour ce contact.\n\nLe format — prise en main au pied levé, mandat de transformation — correspond à mon mode d''intervention. Avant de me positionner, j''ai besoin de quelques éléments pour qualifier la mission :\n\n1. **Taille de la structure** : effectif total et taille de l''équipe R&D / dev concernée ?\n2. **Périmètre exact** : le rôle couvre-t-il uniquement le management de l''équipe de développement, ou inclut-il également l''infrastructure, les opérations IT, la gouvernance SI ?\n3. **Nature de la transformation** : votre message s''est interrompu — pouvez-vous compléter la description ?\n4. **Durée et démarrage** : durée prévisionnelle du mandat et date de démarrage souhaitée ?\n5. **Localisation** : site(s) concerné(s), modalités présentiel / hybride ?\n6. **TJM** : quel est le budget client pour ce profil ?\n\nMon positionnement est celui d''un manager de transition DSI/CTO sur des périmètres IT Ops, infrastructure et transformation organisationnelle — je veux m''assurer que le périmètre R&D / édition logicielle est bien dans mon champ avant d''aller plus loin.\n\nSincères salutations,\nJay"}','executed',NULL,'2026-07-24 11:29:17','2026-07-27 12:26:45',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('32k0cwTF','reminder','{"text": "Consulter l''alerte LeCercle.in \"DSI Groupe\" — mission signalée : Manager Procure-to-Pay (P2P) - Management Relais. Vérifier le brief complet sur le portail : TJM, durée, taille entreprise, sponsor, périmètre mandat (exec ou consultant ?). Qualifier avant toute candidature.", "start_iso": "2026-04-19T09:00:00", "end_iso": "2026-04-19T09:30:00"}','rejected',NULL,'2026-07-25 05:28:57','2026-08-09 23:25:39',NULL,'déjà fait — traité hors cockpit',NULL);
