INSERT INTO "pending_actions" VALUES('9zZWJerK','reply_mail','{"to": "carine.paul@delvillegroup.com", "subject": "RE: Manager de transition DSI/CTO - disponibilite debut aout", "body": "Bonjour Madame,\n\nMerci pour votre retour.\n\nC''est fait : mon inscription sur Mon Espace Manager est finalisée, profil complet et CV déposé.\n\nEn résumé : DSI/CTO de transition, 20 ans d''expérience, sur des structures de 1 000 à 5 000+ collaborateurs (industrie, services, santé, banque/assurance), spécialisé carve-out, post-acquisition et reprise en main de SI en difficulté. Disponible dès le 10 août.\n\nAuriez-vous un créneau la semaine prochaine pour échanger, ou dois-je simplement attendre le relais en interne de votre côté ?\n\nJayson ANGELE\nINOVOPS — Manager de transition DSI / CTO\n+33 (0)6 13 82 61 70"}','executed',NULL,'2026-07-31 12:33:04','2026-08-03 10:38:37',NULL,NULL,NULL);
