INSERT INTO "pending_actions" VALUES('xfvkUr1e','mission_qualification','{"source": "free-work", "external_id": "664031", "titre": "CTO / VP engineering — freelance (6 mois minimum) — Paris La Défense", "url": "https://www.free-work.com/fr/tech-it/job-mission/directeur-des-nouvelles-technologies-directeur-technique-cto/cto-vp-engineering-freelance-6-mois-minimum-paris-la-defense", "contact_email": null, "qualification": {"synthese": "VP Engineering freelance pour reprendre un pôle chez un éditeur logiciel B2B international (~200 pers. en R&D, France + Europe de l''Est), suite à réorganisation de la direction R&D. Paris La Défense, 6 mois à partir de sept. 2026, 1090€/j affiché.", "motifs": ["Rôle de VP Engineering = poste opérationnel de management d''équipe, pas mandat exécutif DSI/CTO", "Structure en 4 pôles sous un nouveau responsable R&D : Jay serait subordonné, pas mandaté en direct", "1090€/j est en dessous du plancher board (750 net) mais loin de la cible EMT/direct visée par le positioning", "Le VP Engineering reporte à qui exactement — au nouveau responsable R&D, au CTO groupe, au CEO ?", "Quel est le périmètre réel de management (nombre de personnes, quel pôle parmi les 4) ?", "Le mandat inclut-il un pouvoir de décision sur l''organisation, le budget, les recrutements, ou est-ce un rôle d''exécution ?", "Pourquoi le poste s''ouvre-t-il maintenant — départ, création, crise sur un des pôles ?", "Intitulé VP Engineering sous un \"nouveau responsable R&D\" suggère poste de N-1 sans autorité pleine", "Description tronquée (\"le client ouvre un poste... pour reprend…\") — contexte réel incomplet", "Ligne hiérarchique précise et niveau d''autorité du VP Engineering", "Périmètre exact (effectifs, pôle concerné, budget)", "Raison de l''ouverture du poste (vacance, création, crise)", "Nom du client final"]}}','rejected',NULL,'2026-08-26 06:19:31','2026-08-26 10:28:12',NULL,'déja traité',NULL);
INSERT INTO "pending_actions" VALUES('9f-58QD-','mission_qualification','{"source": "free-work", "external_id": "6174e8b5a6469fe2", "titre": "CTO / VP engineering — freelance (6 mois minimum) — Paris La Défense", "url": "https://outlook.office365.com/owa/?ItemID=AAMkADA1MWU5NDk2LTY1YjktNGMwMy05ZmFiLWFlOTZlMTk4MTU1YQBGAAAAAAATbMc9knsQRIAnAvTKh8PnBwBjh9rTbUXdTKA8%2FfOASe6cAATdIxe3AABjh9rTbUXdTKA8%2FfOASe6cAAjUwJqOAAA%3D&exvsurl=1&viewmodel=ReadMessageItem", "contact_email": null, "qualification": {"synthese": "Mandat CTO/VP Engineering freelance, 6 mois minimum, sur site Paris La Défense. Client non nommé, publié sur board free-work sans TJM ni date de démarrage précisés.", "motifs": ["Intitulé CTO/VP Engineering suggère un registre exécutif cohérent avec le positionnement visé", "Canal board (free-work) : plancher structurel bas (750 €/j), très en dessous du marché EMT DSI", "Durée 6 mois minimum et lieu Paris compatibles avec les critères, mais rôle et périmètre non détaillés"], "registre": "indetermine", "recommandation": "poursuivre_sous_reserve", "signaux_faibles": ["Aucun descriptif de mission au-delà de l''intitulé, du lieu et de la durée minimale", "Canal board généraliste (free-work) : plancher tarifaire structurellement bas pour un mandat exécutif", "Intitulé \"CTO / VP engineering\" ambigu : peut recouvrir un rôle de direction ou un poste technique senior sans autorité réelle"], "questions": ["Le poste est-il un mandat de direction avec autorité hiérarchique et budgétaire, ou un rôle de contributeur senior sans pouvoir de décision ?", "Quel est le secteur et la taille de l''entreprise cliente (effectifs, contexte de transformation) ?", "Quel est le TJM proposé pour cette mission ?", "Quel est le contexte déclencheur de la mission (carve-out, fusion, dette technique, audit défavorable) ?", "Qui est le sponsor/décideur côté client (CEO, CIO, DRH) ?"], "informations_manquantes": ["Nom et secteur du client final", "Périmètre exact du rôle (équipe, budget, reporting)", "TJM proposé", "Date de démarrage", "Contexte de la mission (raison du recrutement)"]}, "decision": "go"}','executed',NULL,'2026-08-26 06:19:42','2026-08-26 10:27:38',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('5Vzcn-q-','mission_qualification','{"source": "free-work", "external_id": "cb988d10e8896637", "titre": "Directeur de Projet Salesforce – Audit & Gouvernance SI", "url": "https://outlook.office365.com/owa/?ItemID=AAMkADA1MWU5NDk2LTY1YjktNGMwMy05ZmFiLWFlOTZlMTk4MTU1YQBGAAAAAAATbMc9knsQRIAnAvTKh8PnBwBjh9rTbUXdTKA8%2FfOASe6cAATdIxe3AABjh9rTbUXdTKA8%2FfOASe6cAAjVfDZKAAA%3D&exvsurl=1&viewmodel=ReadMessageItem", "contact_email": null, "qualification": {"recommandation": "ecarter", "synthese": "Intitulé seul, pas de descriptif.", "motifs": ["Intitulé ''Directeur de Projet Salesforce'' = pilotage projet outil, pas mandat exécutif DSI/CTO", "Registre technique/applicatif (Salesforce), hors cœur de cible transformation SI post-événement", "Aucun élément de périmètre, secteur, durée ou autorité ne permet d''évaluer le mandat"], "questions": ["Quel est le périmètre exact de la mission (audit SI global ou uniquement Salesforce) ?", "Le rôle inclut-il une autorité de décision (mandat exécutif) ou une posture de chef de projet/consultant ?", "Quel est le secteur et la taille de l''entreprise cliente ?", "Quelle est la durée prévisionnelle et le TJM proposé ?"], "role_attendu": "indetermine", "registre": "technique", "signaux_faibles": ["Intitulé orienté ''Directeur de Projet'' plutôt que DSI/CTO/interim exec", "Spécialisation Salesforce = créneau applicatif éloigné du positionnement infrastructure/transformation SI", "Offre listée en vrac dans une alerte de 40 offres, sans descriptif propre"]}}','rejected',NULL,'2026-08-27 06:19:28','2026-08-28 09:59:24',NULL,'hors cible',NULL);
